/**
 * Returns a file path which does not exist yet, so that an already
 * existing file is never overwritten.
 * If the given path is free, it is returned unchanged. Otherwise an
 * incrementing number is appended to the file name, e.g.
 * "abc_encrypted.pdf" becomes "abc_encrypted(1).pdf".
 *
 * @param path the desired absolute path of the file
 *
 * @return a unique (non existing) absolute file path
 */
public static String getUniqueFileName(String path) {
    if (path == null)
        return null;

    File file = new File(path);
    if (!file.exists())
        return path;

    String parent = file.getParent();
    String fileName = file.getName();
    String baseName = fileName;
    String extension = "";
    int dotIndex = fileName.lastIndexOf('.');
    if (dotIndex > 0) {
        baseName = fileName.substring(0, dotIndex);
        extension = fileName.substring(dotIndex);
    }

    int counter = 1;
    File uniqueFile;
    do {
        String newName = baseName + "(" + counter + ")" + extension;
        uniqueFile = parent == null ? new File(newName) : new File(parent, newName);
        counter++;
    } while (uniqueFile.exists());

    return uniqueFile.getAbsolutePath();
}

